.sonde-drol{--bg:#031322;--panel:#0b2031;--panel2:#163447;--text:#f4f9fd;--muted:#bdd0dc;--line:#34576d;--accent:#53e8f3;color:var(--text);background:var(--bg);font:16px/1.7 system-ui,-apple-system,'Segoe UI',sans-serif;margin:0;overflow-wrap:anywhere}.sonde-drol[data-theme=light]{--bg:#f4f8fb;--panel:#fff;--panel2:#e7f1f7;--text:#09283b;--muted:#405d6c;--line:#b8d3de;--accent:#006e86}.sonde-drol *{box-sizing:border-box}.sonde-drol .wrap{width:min(1160px,100%);margin:auto;padding:clamp(24px,5vw,64px)}.sonde-drol h1,.sonde-drol h2,.sonde-drol h3,.sonde-drol strong{color:var(--text)!important}.sonde-drol h1{font-size:clamp(2.5rem,7vw,5.4rem);line-height:1.02;letter-spacing:-.045em;margin:20px 0}.sonde-drol h2{font-size:clamp(1.8rem,4vw,3rem);line-height:1.15;margin:0 0 18px}.sonde-drol h3{font-size:1.2rem;margin:0 0 10px}.sonde-drol p,.sonde-drol li{color:var(--muted)!important}.sonde-drol .eyebrow{font-size:.75rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--accent)!important}.sonde-drol .hero{background:radial-gradient(circle at 80% 15%,#13526a77,transparent 42%),var(--bg);border-bottom:1px solid var(--line)}.sonde-drol .hero p{max-width:760px;font-size:clamp(1.05rem,2vw,1.25rem)}.sonde-drol .topline,.sonde-drol .actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.sonde-drol .topline{justify-content:space-between}.sonde-drol a.button,.sonde-drol button{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:11px 17px;border:1px solid var(--line);border-radius:10px;color:var(--text)!important;background:linear-gradient(155deg,var(--panel2),var(--panel));box-shadow:inset 0 1px #ffffff66,0 4px 0 #0005,0 9px 18px #0003;font-weight:750;text-decoration:none;cursor:pointer;transition:transform .16s,box-shadow .16s}.sonde-drol a.button:active,.sonde-drol button:active{transform:translateY(3px);box-shadow:inset 0 2px 6px #0006}.sonde-drol :focus-visible{outline:3px solid var(--accent);outline-offset:3px}.sonde-drol .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,245px),1fr));gap:16px}.sonde-drol .card{background:linear-gradient(150deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:14px;padding:24px;box-shadow:inset 0 1px #fff3,0 12px 25px #0003}.sonde-drol .card p:last-child{margin-bottom:0}.sonde-drol .status{display:inline-block;border:1px solid var(--line);border-radius:99px;padding:3px 10px;color:var(--accent);font-size:.75rem;font-weight:700}.sonde-drol section{border-top:1px solid var(--line)}.sonde-drol a:not(.button){color:var(--accent)!important}.sonde-drol .note{border-left:3px solid var(--accent);padding:15px 20px;background:var(--panel2);border-radius:5px}.sonde-drol ul{padding-left:1.2rem}.sonde-drol .steps{counter-reset:step}.sonde-drol .step:before{counter-increment:step;content:'0' counter(step);display:block;color:var(--accent);font-weight:800;margin-bottom:12px}@media(max-width:600px){.sonde-drol .wrap{padding:28px 18px}.sonde-drol .actions a{width:100%}}@media(prefers-reduced-motion:reduce){.sonde-drol *{transition:none!important;scroll-behavior:auto!important}}
